const TOPIC_GROUPS=[
{name:'General knowledge, sport & the wider world',note:'Discover more beyond the classroom.',ids:['general','sports','social','logic']},
{name:'Create, communicate & participate',note:'Explore citizenship, money, making, arts and languages.',ids:['civics','economics','design','arts','languages']},
{name:'Core learning & science',note:'Build a strong Year 6 foundation.',ids:['english','maths','science','biology','chemistry','history','geography','digital','health','music']}
];
const TOPIC_NAMES={general:'General Knowledge',sports:'Sports',social:'Current Issues',logic:'Logic and Puzzles',english:'English & Literacy',civics:'Civics & Citizenship',economics:'Economics & Business',design:'Design & Technologies',arts:'The Arts',digital:'Digital Technologies',health:'Health & PE'};
SUBJECTS.forEach(s=>{if(TOPIC_NAMES[s.id])s.name=TOPIC_NAMES[s.id]});
function topicShortcuts(){return `<section class="field-shortcuts" aria-label="Learning field shortcuts"><b>EXPLORE ALL 19 FIELDS</b><div><button data-subject="general">✺ General Knowledge</button><button data-subject="sports">⚽ Sports</button><button data-action="mixed">Choose any fields →</button></div></section>`}
function subjectCard(s){const a=profile.subjects[s.id]||{correct:0,total:0};return `<button class="subject" data-subject="${s.id}" style="--accent:${s.colour}"><div class="subject-top"><div class="subject-icon">${s.icon}</div><span class="zone">${BANK[s.id].length} QUESTIONS</span></div><h3>${s.name}</h3><p>${s.desc}</p><div class="subject-foot"><span>${s.zone}</span><b>↗</b></div><div class="track"><span style="width:${a.total?a.correct/a.total*100:0}%"></span></div></button>`}
function topicCatalogue(){return `<div class="section-title"><div><h2>All 19 learning fields</h2><p>Choose any mix. Every battle warm-up is 10 questions total.</p></div><span class="count">${QUESTION_COUNT} QUESTIONS & VARIATIONS</span></div>${TOPIC_GROUPS.map(group=>`<section class="catalogue-group"><div class="catalogue-heading"><h3>${group.name}</h3><span>${group.ids.length} fields</span></div><p class="catalogue-note">${group.note}</p><div class="subjects">${group.ids.map(id=>subjectCard(SUBJECTS.find(s=>s.id===id))).join('')}</div></section>`).join('')}`}
function topicPickerGroups(selected){return TOPIC_GROUPS.map(group=>`<section class="picker-group"><h3>${group.name}<small>${group.ids.length} fields</small></h3><div class="picker-group-grid">${group.ids.map(id=>{const s=SUBJECTS.find(s=>s.id===id);return `<button data-topic="${id}" aria-pressed="${selected.includes(id)}" class="topic-choice ${selected.includes(id)?'selected':''}"><span style="color:${s.colour}">${s.icon}</span><b>${s.name}</b><i>${selected.includes(id)?'✓':'+'}</i></button>`}).join('')}</div></section>`).join('')}

